<?php $current = $requirement ?? []; $value = static fn(string $key, mixed $default = '') => old($key, $current[$key] ?? $default); ?>
<form method="post" action="<?= e(url($formAction)) ?>" class="grid gap-5 sm:grid-cols-2">
    <?= csrf_field() ?>
    <div><label class="label">Código o ítem *</label><input name="codigo" class="input" maxlength="30" required value="<?= e($value('codigo')) ?>" placeholder="Ej. 4.11 o RD-03"><?= field_error('codigo') ?></div>
    <div><label class="label">Origen *</label><select name="origen" class="input" required><?php foreach ($origins as $origin): ?><option value="<?= e($origin) ?>"<?= selected($value('origen', 'Requerimiento IVC'), $origin) ?>><?= e($origin) ?></option><?php endforeach; ?></select><?= field_error('origen') ?></div>
    <div><label class="label">Módulo de gestión relacionado *</label><select name="tema" class="input" required><option value="general"<?= selected($value('tema', 'general'), 'general') ?>>Seguimiento general</option><option value="emergencias"<?= selected($value('tema', 'general'), 'emergencias') ?>>Planes de emergencia existentes</option><option value="sgsst"<?= selected($value('tema', 'general'), 'sgsst') ?>>Documentación SG-SST existente</option><option value="capacitaciones"<?= selected($value('tema', 'general'), 'capacitaciones') ?>>Capacitaciones existentes</option><?php foreach ($types as $key => $type): ?><option value="<?= e($key) ?>"<?= selected($value('tema', 'general'), $key) ?>><?= e($type['label']) ?></option><?php endforeach; ?></select><p class="mt-1.5 text-[10px] text-slate-400">Este enlace abre la gestión específica, no sólo el repositorio.</p><?= field_error('tema') ?></div>
    <div><label class="label">Responsable *</label><input name="responsable" class="input" maxlength="250" required value="<?= e($value('responsable', 'Por asignar')) ?>"><?= field_error('responsable') ?></div>
    <div class="sm:col-span-2"><label class="label">Hallazgo o condición de la fuente *</label><textarea name="hallazgo" class="input min-h-24" maxlength="5000" required><?= e($value('hallazgo')) ?></textarea><?= field_error('hallazgo') ?></div>
    <div class="sm:col-span-2"><label class="label">Acción propuesta *</label><textarea name="accion" class="input min-h-28" maxlength="5000" required placeholder="Qué debe ejecutarse y verificarse; una plantilla no reemplaza la acción física"><?= e($value('accion')) ?></textarea><?= field_error('accion') ?></div>
    <div><label class="label">Fecha de compromiso</label><input name="fecha_compromiso" type="date" class="input" value="<?= e($value('fecha_compromiso')) ?>"><?= field_error('fecha_compromiso') ?></div>
    <div><label class="label">Estado de seguimiento *</label><select name="estado" class="input" required><?php foreach ($states as $state): ?><option value="<?= e($state) ?>"<?= selected($value('estado', 'Pendiente'), $state) ?>><?= e($state) ?></option><?php endforeach; ?></select><?= field_error('estado') ?></div>
    <div class="sm:col-span-2"><label class="label">Evidencia mínima esperada</label><textarea name="evidencia_requerida" class="input min-h-20" maxlength="3000"><?= e($value('evidencia_requerida')) ?></textarea><?= field_error('evidencia_requerida') ?></div>
    <div class="sm:col-span-2"><label class="label">Verificación o justificación</label><textarea name="verificacion" class="input min-h-24" maxlength="5000" placeholder="Qué se comprobó, quién verificó, fecha, alcance y resultado. Obligatoria para Cerrado o No aplica."><?= e($value('verificacion')) ?></textarea><?= field_error('verificacion') ?></div>
    <div class="sm:col-span-2 rounded-2xl bg-amber-50 p-4 text-[11px] leading-5 text-amber-900 ring-1 ring-amber-100"><strong>Regla de cierre:</strong> “Cerrado” exige una verificación escrita y al menos una evidencia vinculada con revisión humana. El sistema no valida por sí solo la suficiencia jurídica ni la aceptación de la ETS.</div>
    <div class="sm:col-span-2 flex flex-wrap justify-end gap-3"><button type="submit" class="btn-primary"><?= icon('check', 'h-4 w-4') ?> <?= e($submitLabel ?? 'Guardar requerimiento') ?></button></div>
</form>
